enum ParseError: Error { case notAPort(String) }
func port(_ raw: String) -> Result<Int, ParseError> {
    guard let n = Int(raw.trimmingCharacters(in: .whitespaces)), n > 0 else {
        return .failure(.notAPort(raw))
    }
    return .success(n)
}
let doubled = port(raw).map { $0 * 2 }.mapError { _ in ParseError.notAPort(raw) }
let value = (try? doubled.get()) ?? 8080

